/// The banner a tool writes in the comments that open a file it generated: one of a language's markers, such as
/// `@generated` or `DO NOT EDIT`, in the file's leading run of comments.
///
/// A marker inside a backtick span is a mention, as documentation of the convention quotes it, and a marker below the
/// first code is no banner, because a hand-written file may mention the phrase. An empty marker or comment token
/// matches nothing.
///
/// # Examples
///
/// ```
/// use kartta_lang::Banner;
///
/// const BANNER: Banner = Banner::new(&["@generated", "DO NOT EDIT"])
///     .with_lines(&["//"])
///     .with_block("/*", "*/");
///
/// assert!(BANNER.opens(b"/* Licensed. */\n// Code generated by protoc. DO NOT EDIT.\nint f();\n"));
/// assert!(!BANNER.opens(b"// Files carrying a `@generated` header are machine output.\nint f();\n"));
/// assert!(!BANNER.opens(b"int f();\n// @generated\n"));
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Banner {
    markers: &'static [&'static str],
    line_comments: &'static [&'static str],
    block_comment: Option<(&'static str, &'static str)>,
}

enum HeaderLine {
    Marked,
    Comment,
    InBlock(&'static str),
    Code,
}

impl Banner {
    /// A banner any of `markers` announces, in no comment yet: [`Banner::marks`] reads a comment for it, and
    /// [`Banner::opens`] finds it only in the comment forms added with [`Banner::with_lines`] and
    /// [`Banner::with_block`].
    #[must_use]
    pub const fn new(markers: &'static [&'static str]) -> Self {
        Self {
            markers,
            line_comments: &[],
            block_comment: None,
        }
    }

    /// This banner, also in comments that start with one of `prefixes` and run to the end of their line.
    #[must_use]
    pub const fn with_lines(self, prefixes: &'static [&'static str]) -> Self {
        Self {
            line_comments: prefixes,
            ..self
        }
    }

    /// This banner, also in comments that `open` opens and `close` closes, on one line or across several.
    #[must_use]
    pub const fn with_block(self, open: &'static str, close: &'static str) -> Self {
        Self {
            block_comment: Some((open, close)),
            ..self
        }
    }

    /// Whether the comments that open `source` announce this banner.
    ///
    /// Those are the leading run of blank lines and comments, after a UTF-8 byte order mark, up to the first line that
    /// starts with anything else. A block comment closed on its line leaves the rest of the line to be read as a line
    /// of its own, so a comment after it is still read and code after it ends the run; a marker counts only in comment
    /// text, never in that code. The scan stops at the end of the run and allocates nothing.
    #[must_use]
    pub fn opens(&self, source: &[u8]) -> bool {
        let source = source.strip_prefix(b"\xEF\xBB\xBF").unwrap_or(source);
        let mut open_block = None;
        for line in source.split(|&byte| byte == b'\n') {
            match self.header_line(line.trim_ascii(), open_block) {
                HeaderLine::Marked => return true,
                HeaderLine::Comment => open_block = None,
                HeaderLine::InBlock(close) => open_block = Some(close),
                HeaderLine::Code => return false,
            }
        }

        false
    }

    /// Whether `comment` announces this banner: holds one of its markers outside a backtick span.
    #[must_use]
    pub fn marks(&self, comment: &[u8]) -> bool {
        let mut outside_span = true;
        for (at, &byte) in comment.iter().enumerate() {
            if outside_span && starts_with_any(&comment[at..], self.markers) {
                return true;
            }
            outside_span ^= byte == b'`';
        }

        false
    }

    fn header_line(&self, mut line: &[u8], open_block: Option<&'static str>) -> HeaderLine {
        if let Some(close) = open_block {
            let Some(end) = find(line, close) else {
                return self.marked_or(line, HeaderLine::InBlock(close));
            };
            if self.marks(&line[..end]) {
                return HeaderLine::Marked;
            }
            line = line[end + close.len()..].trim_ascii();
        }

        loop {
            if line.is_empty() {
                return HeaderLine::Comment;
            }
            if starts_with_any(line, self.line_comments) {
                return self.marked_or(line, HeaderLine::Comment);
            }
            let Some((open, close)) = self.block_comment.filter(|(open, _)| !open.is_empty())
            else {
                return HeaderLine::Code;
            };
            let Some(body) = line.strip_prefix(open.as_bytes()) else {
                return HeaderLine::Code;
            };
            let Some(end) = find(body, close) else {
                return self.marked_or(line, HeaderLine::InBlock(close));
            };

            let comment_end = open.len() + end + close.len();
            if self.marks(&line[..comment_end]) {
                return HeaderLine::Marked;
            }
            line = line[comment_end..].trim_ascii();
        }
    }

    fn marked_or(&self, comment: &[u8], unmarked: HeaderLine) -> HeaderLine {
        if self.marks(comment) {
            HeaderLine::Marked
        } else {
            unmarked
        }
    }
}

fn starts_with_any(text: &[u8], tokens: &[&str]) -> bool {
    tokens
        .iter()
        .any(|token| !token.is_empty() && text.starts_with(token.as_bytes()))
}

fn find(haystack: &[u8], needle: &str) -> Option<usize> {
    if needle.is_empty() {
        return None;
    }
    haystack
        .windows(needle.len())
        .position(|window| window == needle.as_bytes())
}

#[cfg(test)]
mod tests {
    use super::*;

    const C: Banner = Banner::new(&["@generated", "DO NOT EDIT", "Code generated"])
        .with_lines(&["//"])
        .with_block("/*", "*/");
    const HASH: Banner = Banner::new(&["@generated", "DO NOT EDIT"]).with_lines(&["#"]);

    #[test]
    fn each_marker_in_a_leading_comment_announces_the_banner() {
        for source in [
            &b"// @generated by tool\nvoid emitted() {}\n"[..],
            b"// DO NOT EDIT\nvoid emitted() {}\n",
            b"// Code generated by tool.\nvoid emitted() {}\n",
            b"/*\n * DO NOT EDIT.\n */\nvoid emitted() {}\n",
        ] {
            assert!(C.opens(source), "{}", String::from_utf8_lossy(source));
        }
        assert!(!C.opens(b"\nvoid emitted() {}\n"));
    }

    #[test]
    fn a_byte_order_mark_before_the_banner_hides_nothing() {
        assert!(C.opens(b"\xEF\xBB\xBF// @generated by tool\nvoid emitted() {}\n"));
        assert!(C.opens(b"\xEF\xBB\xBF/* DO NOT EDIT */\nvoid emitted() {}\n"));
        assert!(!C.opens(b"\xEF\xBB\xBF// a header\nvoid written() {}\n"));
        assert!(HASH.opens(b"\xEF\xBB\xBF# @generated\nclass a {}\n"));
    }

    #[test]
    fn the_first_code_ends_the_header() {
        assert!(HASH.opens(b"\n# DO NOT EDIT\nclass a {}\n"));
        assert!(!HASH.opens(b"class a {\n  # @generated\n}\n"));
        assert!(!HASH.opens(b"# a plain module\nclass a {}\n"));
        assert!(
            !HASH.opens(b"/* @generated */\nclass a {}\n"),
            "a form the banner does not name is code"
        );
    }

    #[test]
    fn code_after_a_block_closed_on_its_line_ends_the_header() {
        assert!(
            !C.opens(b"/*\n * module header\n */ int CONST = 1;\n// DO NOT EDIT\nvoid real() {}\n")
        );
        assert!(!C.opens(b"/* header */ int x = 0;\n// DO NOT EDIT\nvoid coded() {}\n"));
        assert!(!C.opens(b"/* header */ const char* TAG = \"DO NOT EDIT\";\nvoid tagged() {}\n"));
        assert!(C.opens(b"/* @generated by tool */\nvoid emitted() {}\n"));
        assert!(C.opens(b"/* license */ // @generated by tool\nvoid emitted() {}\n"));
    }

    #[test]
    fn a_header_that_quotes_a_marker_only_mentions_it() {
        let mention = b"/*\n * Files carrying a `@generated` or `DO NOT EDIT` header are machine output.\n */\n\
                        void f() {}\n";

        assert!(!C.opens(mention));
        assert!(C.opens(b"// Code generated by `gen.exe`. DO NOT EDIT.\nvoid emitted() {}\n"));
    }

    #[test]
    fn an_empty_marker_or_comment_token_matches_nothing() {
        let empty = Banner::new(&["", "@generated"])
            .with_lines(&[""])
            .with_block("", "");
        let unclosed = Banner::new(&["@generated"])
            .with_lines(&["//"])
            .with_block("/*", "");

        assert!(!empty.marks(b"// an ordinary header"));
        assert!(!empty.opens(b"// @generated\nint f();\n"));
        assert!(
            unclosed.opens(b"/* a header */\nint f();\n// @generated\n"),
            "an empty closing token closes nothing"
        );
    }

    #[test]
    fn a_marker_outside_every_backtick_span_announces_the_banner() {
        assert!(C.marks(b"// Code generated by protoc-gen-go. DO NOT EDIT."));
        assert!(C.marks(b"/* Automatically @generated by tree-sitter */"));
        assert!(C.marks(b"// see `docs.md`: @generated"));
        assert!(!C.marks(b"//! a `@generated` / `DO NOT EDIT` marker in the leading comment run"));
        assert!(
            !C.marks(b"//! every symbol test code, a `// Code generated ... DO NOT EDIT.` header")
        );
        assert!(!C.marks(b"// see `docs.md: @generated"));
        assert!(!C.marks(b"// an ordinary header"));
        assert!(!C.marks(b""));
    }
}
